$f=null;$workers=[];
try{
 $f=new AddressRegisterImportFixture();$r=AddressRegisterWorkbookFixture::row('RACE-1');$p1=$f->preview([$r]);$p2=$f->preview([$r]);assertSameValue('ready',$p1['status'],'first race preview');assertSameValue('ready',$p2['status'],'second race preview');$env=$f->base->environment();$beforeCount=(int)$f->db->query("SELECT COUNT(*) FROM {$f->p}fm_maintable")->fetch_column();
