 $statuses=array_column($out,'status');assertSameValue(1,count(array_filter($statuses,static fn($s)=>$s==='applied')),'one creation winner');$loser=current(array_filter($out,static fn($x)=>$x['status']!=='applied'));assertSameValue(true,$loser['status']==='replayed'||($loser['reasonCode']??'')==='PREVIEW_STALE','loser is replay or stale');assertSameValue($beforeCount+1,(int)$f->db->query("SELECT COUNT(*) FROM {$f->p}fm_maintable")->fetch_column(),'one object despite race');$id=$f->id('RACE-1');assertSameValue(1,(int)$f->db->query("SELECT COUNT(*) FROM {$f->p}fm2_installation_cases WHERE legacy_installation_object_id=$id")->fetch_column(),'one case');assertSameValue(1,(int)$f->db->query("SELECT COUNT(*) FROM {$f->p}fm2_object_detail_edit_events WHERE object_id=$id")->fetch_column(),'one creation history event');
