 try{$a=$f->apply($p,'77777777-7777-4777-8777-000000000010');assertSameValue('failed',$a['status'],'late apply fails');assertSameValue([0,0,0,0],[$a['summary']['created'],$a['summary']['updated'],$a['summary']['filled'],$a['summary']['replaced']],'failed apply reports zero published changes');assertSameValue($before,$f->business(true),'ALL business tables rollback, not just one field');assertSameValue('failed',$f->owner->report($p['packageId'])['status'],'durable failure report remains');}finally{$f->db->query("DROP TRIGGER {$f->p}import_late_fault");}
 // Real server commit succeeded; caller receives a transport-like commit exception.
