 $deadline=microtime(true)+20;while(count(glob($f->root.'/cache-ready-*'))!==2){if(microtime(true)>$deadline)throw new TestFailure('cache race barrier timeout');usleep(10000);}touch($release);foreach($workers as$i=>$w){assertSameValue(0,proc_close($w),'cache child');unset($workers[$i]);$r=json_decode(file_get_contents($f->root.'/cache-result-'.$i),true,flags:JSON_THROW_ON_ERROR);assertSameValue(true,$r['status']==='ready'||($r['reasonCode']??'')==='CACHE_BUSY','serialized preview result');}
 assertSameValue(1,count(file($log,FILE_IGNORE_NEW_LINES)),'one paid attempt across concurrent packages');
 echo "PASS ADDRESS-REGISTER-IMPORT-001 A08-A09 atomic concurrency\n";
}finally{foreach($workers as$w){proc_terminate($w);proc_close($w);}if($f)$f->close();}
